INSERT INTO `leave_types` VALUES (1,'Annual Leave','လုပ်သက်ခွင့်','ANNUAL','Annual Leave is','လုပ်သက်ခွင့်သည် တာဝန်ထမ်းဆောင်သည့်ကာလကို အခြေပြု၍ ရခွင့်ရှိသော ခွင့်ဖြစ်သည်။ ရခွင့်ရှိ သောကာလမှာ တာဝန်ချိန်၏ (၁/၁၁) ဖြစ်သည်။ အချိန်ပြည့်တာဝန်ထမ်းဆောင်ရက် ၁၁ ရက်ရှိတိုင်း လုပ်သက်ခွင့် တစ်ရက်စုဆောင်းခွင့်ရှိပြီး ရုံးပိတ်ရက်များရှိလျှင်လည်း တစ်ဆက်တည်း ထည့်သွင်း တွက်ချက်သည်။ လုပ်သက်ခွင့်ကို ​ဆေးလက်မှတ်ခွင့်နှင့်လစာမဲ့ခွင့်တို၏ ရှေ့မှဖြစ်စေ၊ နောက်မှဖြစ်စေ၊ တစ်ဆက်တည်း ဆက်စပ် ခံစားခွင့်ရှိသည်။ အငြိမ်းစားယူရန် ကြိုတင်ပြင်ဆင်ခွင့်ကို ငြင်းပယ်ထားသည့်ကိစ္စမှတစ်ပါး အငြိမ်းစားယူရမည့်နေ့ ရက်ထက်ကျော်၍ ခံစားခွင့်မရှိစေရ။ လုပ်သက်ခွင့်ကာလအတွင်း၌ ပျမ်းမျှလစာကို ခွင့်လစာအဖြစ် ခံစားခွင့်ရှိသည်။',30,NULL,5,0,0,1,'2026-08-18 10:35:56','2026-08-31 13:23:08'),(2,'Medical Leave','ဆေးခွင့်','MEDICAL','ဆေးလက်မှတ်ခွင့်သည် တာဝန်ထမ်းဆောင်သည့်ကာလကို အခြေမခံဘဲ လုပ်သက်နုရင့် မရွေးခွင့်ပြုနိုင်သည့် ခွင့်မျိုးဖြစ်သည်။ ဆေးလက်မှတ်ခွင့်ကို ခွင့်ပြုရာတွင်-\r\n\r\n(က) ဝန်ထမ်းလုပ်သက်တစ်လျှောက်လုံးအတွက် ခွင့်ပြုနိုင်သည့်ကာလသည် ၁၂ လဖြစ်သည်။ အထူးလုံလောက် သောကိစ္စများတွင် နောက်ထပ်ခြောက်လထိ ထပ်မံခွင့်ပြုနိုင်သည်။\r\n\r\n(ခ) ကျန်းမာရေးဝန်ကြီးဌာနကသတ်မှတ်ထားသည့် ဆရာဝန် သို့မဟုတ် ဆေးအဖွဲ့၏ ထောက်ခံချက်ကို တင်ပြမှ သာခွင့်ပြုရမည်။ တစ်ကြိမ်လျှင်မည်မျှခွင့်ပြုရမည်ဟု သတ်မှတ်ချက်မရှိသော်လည်း ဆေးလက်မှတ်၌ ထောက်ခံထား သည့်ကာလထက် ကျော်လွန်၍ခွင့်မပြုရ။\r\n\r\n(ဂ) ဝန်ထမ်းတစ်ဦးသည် ဆေးလက်မှတ်ခွင့်ကုန်ဆုံးချိန်တွင် ကျန်းမာစွာဖြင့် တာဝန်ပြန်လည် ထမ်းဆောင်နိုင်ဖွယ် အခြေအနေရှိသည်ဟု ဆရာဝန် သို့မဟုတ် ဆေးအဖွဲ့ကမှတ်ချက်ပြုမှသာ ဆေးလက်မှတ်ခွင့်ကိုခွင့်ပြုရမည်။\r\n\r\n(ဃ) ဝန်ထမ်းသည် ဆေးလက်မှတ်ခွင့်အစားလုပ်သက်ခွင့်ခံစားခွင့်ပြုရန် တောင်းခံပါက လုပ်သက်ခွင့် ကို ခွင့်ပြု နိုင်သည်။ ယင်းသို့ခွင့်ပြုသည့် လုပ်သက်ခွင့်ကာလကို နည်းဥပဒေခွဲ (က)တွင် ပါရှိသည့် ဆေးလက်မှတ်ခွင့်ကာလ သတ်မှတ်ချက်တွင် ထည့်သွင်းတွက်ချက်ခြင်းမပြုရ။',NULL,15,NULL,5,1,0,1,'2026-08-18 10:35:56','2026-08-18 17:03:06'),(3,'Casual Leave','ရှောင်တခင်ခွင့်','CASUAL','ရှောင်တခင်ခွင့်သည် ရုတ်တရက်နာမကျန်းဖြစ်ခြင်းကြောင့်လည်းကောင်း၊ အရေးကြီးသော ကိုယ်ရေးကိစ္စရုတ်ချည်း ပေါ်ပေါက်ခြင်းကြောင့်လည်းကောင်း အလုပ်ခွင်သို့မလာရောက်ဘဲ နေခွင့်ပြုသည့် ခွင့်ရက်တိုဖြစ်သည်။ ရှောင်တခင်ခွင့်ခံစားနေသည့် ဝန်ထမ်းကို အလုပ်ခွင်၌ ရှိနေသကဲ့သို့ မှတ်ယူရမည်။ ရှောင်တခင်ခွင့်ကို ခွင့်ပြုရာတွင်-\r\n\r\n(က) အလုပ်ခွင်သို့မလာရောက်နိုင်သည့်နေ့ရက်များအတွက် ရှောင်တခင်ခွင့်တောင်းခံရမည်။\r\n\r\n(ခ) ရှောင်တခင်ခွင့်ခံစားသူသည် ခွင့်ပေးပိုင်ခွင့်ရှိသူ၏ ခွင့်ပြုချက်မရဘဲ တာဝန်ကျရာဒေသမှ ထွက်ခွာခွင့်မရှိစေရ။\r\n\r\n(ဂ) သာမန်အားဖြင့် ပြက္ခဒိန်နှစ်တစ်နှစ်အတွင်း၌ ရှောင်တခင်ခွင့် ၁၀ ရက်ထက်ပို၍ ခွင့်မပြုရ။\r\n\r\n(ဃ) သို့ရာတွင် ခိုင်လုံသည့်အကြောင်းရှိပါက ပြက္ခဒိန်နှစ်တစ်နှစ်အတွင်း၌ ၁၀ ရက်ထက်ပို၍ ခွင့်ပြုနိုင်သည်။ ယင်းသို့ခွင့်ပြုရခြင်းသည် ယခင်ခံစားပြီးဖြစ်သည့် ရှောင်တခင်ခွင့်ရက်များတွင် ရုံးပိတ်ရက်များပါ ဝင်ခဲ့ခြင်း သို့မဟုတ် ယခုတောင်းခံသည့် ရှောင်တခင်ခွင့်ရက်များတွင် ရုံးပိတ်ရက် ပါဝင်နေခြင်း တို့အတွက် ရှောင်တခင်ခွင့် ၁၀ ရက်ထက်ပိုပြီး ခွင့်ပြုပေးရန် ခိုင်လုံသည့် အကြောင်းများရှိလျှင် ခွင့်ပြုပိုင်ခွင့်ရှိသူက ထည့်သွင်းစဉ်းစားပြီး ခွင့်ပြုပေးရန် ဖြစ်သည်။\r\n\r\n(င) သွေးလှူသည့်နေ့ရက်နှင့် နောက်တစ်ရက်ကို အထူးရှောင်တခင်ခွင့်အဖြစ် သီးသန့်ခံစားခွင့်ရှိသည်။ သို့ရာတွင် ရှောင်တခင်ခွင့် ၁၀ ရက်တွင် ယင်းနှစ်ရက်ကို ထည့်သွင်းရေတွက်ခြင်းမပြုရ။ အခြားခွင့်များနှင့် ရှေ့နောက်ဆက်၍ခွင့်မပြုရ။\r\n\r\n(စ) ရှောင်တခင်ခွင့်ရက်အတွက် တာဝန်ချိန်လစာနှုန်းပြည့်ကို ခံစားခွင့်ရှိသည်။\r\n\r\n(ဆ) ရှောင်တခင်ခွင့်ကို အခြားခွင့်များနှင့်ဖြစ်စေ၊ ကူးပြောင်းချိန်နှင့်ဖြစ်စေ၊ အားလပ်ရက်ရှည်နှင့် ဖြစ်စေ ဆက်၍ခွင့်မပြုရ။ ရှောင်တခင်ခွင့်နှင့် တစ်ဆက်တည်း အခြားခွင့်တစ်မျိုးကိုတောင်းခံခဲ့သော် ရှောင်တခင် ခွင့်ပျက်ပြယ်သွားပြီးနောက် ရှောင်တခင်ခွင့်နှင့်ဆက်၍ တောင်းခံသောခွင့်ကို ရှောင်တခင် ခွင့်စသည့် နေ့ရက်မှစ၍ ခွင့်ပြုရမည်။\r\n\r\n(ဇ) ရှောင်တခင်ခွင့်အတွက် ခွင့်မှတ်တမ်းများကို ခွင့်ပြုပိုင်ခွင့်ရှိသူထံတွင် ထားရှိရမည်။',NULL,10,3,5,0,0,1,'2026-08-18 10:35:56','2026-08-18 23:32:28'),(4,'Study Leave','ပညာလေ့လာဆည်းပူးခွင့်','STUDY','ပညာလေ့လာဆည်းပူးခွင့်ဆိုသည်မှာ နိုင်ငံတော်၏အကျိုးငှာ ဝန်ကြီးဌာနနှင့် အဖွဲ့အစည်းအကြီး အမှူးက အဆိုပြု၍ နိုင်ငံခြားပညာတော်သင်စိစစ်ရွေးချယ်စေလွှတ်ရေးကော်မတီ၏ ထောက်ခံတင်ပြမှု အပေါ် ပြည်ထောင်စုအစိုးရအဖွဲ့၏ ခွင့်ပြုချက်အရ ပြည်ပတွင် ဒီပလိုမာ၊ ဘွဲ့လွန်၊ ပါရဂူဘွဲ့တက်ရောက် ခြင်း သို့မဟုတ် ပညာရပ်အတွေ့အကြုံတစ်ခုခုကို သွားရောက်လေ့လာခြင်းကို ဆိုသည်။\r\nပညာလေ့လာဆည်းပူးခွင့်ကာလကို သက်ဆိုင်ရာဝန်ကြီးဌာနနှင့် အဖွဲ့အစည်းအကြီးအမှူးက တာဝန်ချိန်အဖြစ် သတ်မှတ်ပြီး လစာနှုန်းပြည့်ခံစားခွင့်ပြုရမည်။\r\nပြည်ပသို့သွားရောက်ရသည့် နိုင်ငံခြားပညာသင်များသည် နိုင်ငံတော်က သတ်မှတ်ခွင့်ပြုသည့် ဝတ်စုံစရိတ်၊ အသေးသုံးစရိတ်တို့ကို ခံစားခွင့်ရှိသည်။ ထို့ပြင် ပညာသင်ဆုကမ်းလှမ်းသည့်နိုင်ငံ သို့မဟုတ် အဖွဲ့အစည်းကထောက်ပံ့ပေးသော ပညာသင်စရိတ်၊ အသုံးစရိတ်တို့ကိုလည်းခံစားခွင့်ရှိသည်။',NULL,0,NULL,5,1,1,1,'2026-08-18 10:35:56','2026-08-18 17:04:25'),(5,'Maternity Leave','မီးဖွားခွင့်','Maternity','(က) အမျိုးသမီးဝန်ထမ်းများသည် မီးဖွားခွင့်ကို စတင်ခံစားသည့်နေ့ရက်မှစ၍ ခြောက်လအထိ ခံစားခွင့်ရှိသည်။\r\n\r\n(ခ) မီးဖွားခွင့်ကို ခွင့်ပြုရာတွင်-\r\n\r\n(၁) အခြားခွင့်များနှင့် ဆက်စပ်၍ ခွင့်မပြုရ။\r\n\r\n(၂) ဆေးလက်မှတ်အထောက်အထားဖြင့် တောင်းခံပါက အခြားခွင့်များကို မီးဖွားခွင့်၏ နောက်မှ ဆက်၍ ခွင့်ပြုနိုင်သည်။\r\n\r\n(၃) ကိုယ်ဝန်ဆောင်နေသည့် ကာလအတွင်းသန္ဓေပျက်ကျသည့် အခြေအနေမျိုးတွင် ဆေးလက်မှတ် အထောက်အထားဖြင့် ခြောက်ပတ်ထက်မပိုသည့် မီးဖွားခွင့်ကို ခွင့်ပြုရမည်။\r\n\r\n(၄) သန္ဓေပျက်ရန် စိုးရိမ်ဖွယ်ရာရှိသောအခြေအနေမျိုးအတွက် မီးဖွားခွင့်မပေးရ။ အခြားသင့်လျော်ရာ ခွင့်သာခွင့်ပြုရမည်။\r\n\r\n(၅) ကိုယ်ဝန်အဆိပ်တက်ခြင်းတွင် မီးဖွားခွင့်ကို မထိခိုက်စေဘဲ ဆေးလက်မှတ်ဖြင့် ခြောက်ပတ် ထက်မပိုသော သင့်လျော်သည့် ခွင့်ပေးရမည်။\r\n\r\n(၆) အမြွှာပူး သို့မဟုတ် ယင်းထက်ပို၍ မွေးဖွားပါက သာမန်မီးဖွားခွင့်ကုန်ဆုံးရက်၏ နောက်ရက်မှစပြီး ကလေးများပြုစုစောင့်ရှောက်နိုင်ရန် ရက်သတ္တပတ်ခြောက်ပတ်တိုး၍ မီးဖွားခွင့်အဖြစ်ခွင့်ပြုရမည်။\r\n\r\n(ဂ) မီးဖွားသောအမျိုးသမီး၏ခင်ပွန်းသည် ဝန်ထမ်းဖြစ်လျှင် မွေးကင်းစကလေး ပြုစုစောင့်ရှောက်ခွင့် ရရှိရေးအတွက် ခင်ပွန်းဖြစ်သူကို ရက်သတ္တပတ်နှစ်ပတ် ခွင့်ပြုရမည်။ ယင်းရက်သတ္တပတ်နှစ်ပတ်ကို တာဝန်ချိန်အဖြစ် သတ်မှတ်ပြီး လစာနှုန်းပြည့် ခံစားခွင့်ပြုရမည်။',NULL,180,NULL,5,1,0,1,'2026-08-18 14:33:02','2026-08-18 17:05:29'),(6,'Emergency Leave','အရေးပေါ်ခွင့်','Emergency','Emergency leave is ....','အရေးပေါ်ခွင့် ဆိုသည်မှာ',0,NULL,5,0,1,1,'2026-08-18 14:34:53','2026-08-31 13:20:29'),(11,'Maternity Leave lll','မီးဖွားခွင့်','Maternity kkk','aaa','မမမမမမမ',100,NULL,5,0,0,1,'2026-08-29 15:43:27','2026-08-29 15:53:38'),(12,'Quarantine Leave','ကာကွယ်ဆေးခွင့်','QL','Quarantine Leave is','ကာကွယ်ဆေးခွင့်ဆိုသည်မှာ',0,NULL,5,0,1,1,'2026-08-29 16:02:45','2026-08-29 16:23:37');
